 async function startOperation(fixture,args){mutationGuard();if(busy)throw new Error('Wait for the current operation.');busy=true;root.sessionStorage.setItem('c2bPendingStart',JSON.stringify({fixture,args,actor}));try{const result=await rpc(fixture,'start',args);if(!result.done)await advance(fixture,result.id);else {await refreshCatalog();await openIssue(fixture);}root.sessionStorage.removeItem('c2bPendingStart');return result;}catch(error){if(error.code){root.sessionStorage.removeItem('c2bPendingStart');root.sessionStorage.removeItem('c2bPendingJob');}throw error;}finally{busy=false;renderActive();}}
